"""Bounded resource measurements of disarmed final driver using generated bytes.

Fresh process per scenario. No dependencies downloaded, installed or executed.
Reported RSS is cumulative process high-water (Windows peak working set).
Storage is logical file length, not filesystem allocation or physical I/O.
"""
from contextlib import contextmanager, nullcontext
import io
import json
import os
from pathlib import Path
import sys
import tempfile
import time
from unittest.mock import patch
import zipfile

sys.path.insert(0,str(Path(__file__).resolve().parent))
import wheel_hosted_final as f
import wheel_acquisition_offline as a
import wheel_archive_inspector as w
import wheel_archive_inspector_v2 as v2
import wheel_notice_evidence_v2 as n
import wheel_license_policy as p
from test_wheel_acquisition_offline import candidate,wire
from test_wheel_archive_inspector import D

MIB=1024*1024

def need(ok,reason):
    if not ok: raise AssertionError(reason)

def peak():
    if sys.platform=='win32':
        import ctypes
        from ctypes import wintypes
        class Counters(ctypes.Structure):
            _fields_=[('cb',wintypes.DWORD),('PageFaultCount',wintypes.DWORD)]+[
                (x,ctypes.c_size_t) for x in ('PeakWorkingSetSize','WorkingSetSize',
                'QuotaPeakPagedPoolUsage','QuotaPagedPoolUsage','QuotaPeakNonPagedPoolUsage',
                'QuotaNonPagedPoolUsage','PagefileUsage','PeakPagefileUsage')]
        kernel=ctypes.WinDLL('kernel32',use_last_error=True)
        psapi=ctypes.WinDLL('psapi',use_last_error=True)
        kernel.GetCurrentProcess.restype=wintypes.HANDLE
        psapi.GetProcessMemoryInfo.argtypes=[wintypes.HANDLE,ctypes.POINTER(Counters),wintypes.DWORD]
        psapi.GetProcessMemoryInfo.restype=wintypes.BOOL
        counters=Counters();counters.cb=ctypes.sizeof(counters)
        need(psapi.GetProcessMemoryInfo(kernel.GetCurrentProcess(),ctypes.byref(counters),counters.cb),
             'MEMORY_COUNTER')
        return counters.PeakWorkingSetSize
    import resource
    need(sys.platform.startswith('linux'),'MEASUREMENT_PLATFORM')
    return resource.getrusage(resource.RUSAGE_SELF).ru_maxrss*1024

def logical(root):
    return sum(x.stat().st_size for x in root.rglob('*') if x.is_file())

def stage(label,started,root):
    return {'stage':label,'seconds':round(time.perf_counter()-started,6),
            'peak_rss_bytes':peak(),'retained_logical_bytes':logical(root)}

def item(build=None,**kwargs):
    raw,row=candidate(build=build,**kwargs)
    return raw,row,p.binding(row['filename'],row['metadata_sha256'],'2.4',row['license_files'])

def scenario(name):
    if name=='stored':
        # ~97% of individual archive ceiling, no inflated expansion.
        return [item(compress=zipfile.ZIP_STORED,changes={'demo_pkg/data.bin':b'A'*(34*MIB)})]
    if name=='dense':
        return [item(changes={f'demo_pkg/data/f{i:05d}.txt':b'x' for i in range(47993)})]
    if name=='notices63':
        # 31 MiB of notices + small fixture notices, across 63 unique rows.
        rows=[]
        for i in range(1,64):
            count=8 if i<=3 else 7 if i==4 else 0
            changes={D+f'licenses/notice{j:02d}.txt':bytes([65+j])*MIB for j in range(count)}
            rows.append(item(i,changes=changes))
        return rows
    raise ValueError('SCENARIO')

def setup(items):
    rows=[x[1] for x in items]
    bindings={x[1]['filename']:x[2] for x in items}
    replay=a.Replay({x[1]['url']:wire(x[0]) for x in items})
    return rows,bindings,replay

def caps_for(rows):
    return {'body':sum(r['bytes'] for r in rows),'expanded':v2.MAX_TOTAL,
            'notice':v2.MAX_NOTICES,'evidence':n.MAX_EVIDENCE_BATCH}

def collect(name):
    with tempfile.TemporaryDirectory(prefix='c5-inert-resource-') as temp:
        parent=Path(temp);base=peak();started=time.perf_counter()
        items=scenario(name);rows,bindings,replay=setup(items);del items
        caps=caps_for(rows)
        stages=[stage('fixture_generation',started,parent)]
        scratch=[];real=tempfile.TemporaryFile
        @contextmanager
        def tracked(*args,**kwargs):
            with real(*args,**kwargs) as stream:
                try: yield stream
                finally:
                    stream.flush()
                    scratch.append(os.fstat(stream.fileno()).st_size)
        started=time.perf_counter()
        with patch.object(a.tempfile,'TemporaryFile',tracked):
            path,digest=f._collect(rows,'resource-fixture',bindings,caps,f.FIXTURE_SCOPE,
                                   replay.get,nullcontext,parent)
        stages.append(stage('collection',started,parent))
        need(len(replay.requests)==len(rows) and len(scratch)==len(rows),'REQUEST_COUNT')
        need(scratch==[r['bytes'] for r in rows],'SCRATCH_LENGTH')
        started=time.perf_counter()
        manifest=f.verify_generation(path,digest,rows,'resource-fixture',scope=f.FIXTURE_SCOPE,
                                     bindings=bindings,caps=caps)
        stages.append(stage('producer_replay',started,parent))
        need(manifest['verified_count']==len(rows) and manifest['received_bytes']==caps['body'],
             'COLLECTION_SETTLEMENT')
        need(manifest['status']=='CANDIDATE_EVIDENCE_RECORDED' and manifest['production_ready'] is False,
             'SYNTHETIC_STATUS')
        totals=manifest['accepted_totals']
        started=time.perf_counter()
        bundle,ident=f.export_generation(path,digest,rows,'resource-fixture',parent,bindings=bindings,
                                         caps=caps,scope=f.FIXTURE_SCOPE)
        record=f.artifact_record('12345','1'*40,ident,rows,'resource-fixture',bindings=bindings,
                                 caps=caps,scope=f.FIXTURE_SCOPE)
        expected=f._settlement(path,manifest,digest,rows)
        stages.append(stage('bundle_export_including_replay',started,parent))
        started=time.perf_counter()
        out=io.BytesIO()
        with zipfile.ZipFile(out,'w',compression=zipfile.ZIP_STORED) as z:
            z.write(bundle,'receipts.odin')
        raw=out.getvalue();del out
        zip_sha=w.sha(raw)
        stages.append(stage('local_outer_zip',started,parent))
        meta={'id':123,'name':record['artifact_name'],'expired':False,'size_in_bytes':len(raw),
              'digest':'sha256:'+zip_sha,'workflow_run':{'id':12345,'head_sha':'1'*40,
              'head_branch':f.BRANCH.removeprefix('refs/heads/')}}
        # Release producer artifacts and fixture HTTP payloads before replay,
        # modeling the separate retriever, but cumulative RSS remains high-water.
        del replay
        started=time.perf_counter()
        observed=f._replay(raw,meta,record,expected,'12345','1'*40,123,zip_sha,
                          rows,'resource-fixture',parent,bindings=bindings,caps=caps,scope=f.FIXTURE_SCOPE)
        stages.append(stage('independent_zip_replay',started,parent))
        need(n.canonical(observed)==n.canonical(expected),'SETTLEMENT_MISMATCH')
        receipts=[json.loads((path/f'wheel-{i:03d}-evidence.json').read_bytes())['receipt']
                  for i in range(1,len(rows)+1)]
        members=max(r['members']+r['directory_entries'] for r in receipts)
        if name=='stored': need(max(scratch)>0.97*v2.MAX_ARCHIVE,'STORED_TARGET')
        if name=='dense': need(members==48000,'DENSE_TARGET')
        if name=='notices63': need(len(rows)==63 and totals['notice']>=31*MIB,'NOTICES_TARGET')
        need(ident['bytes']<=f.bundle_cap(caps) and len(raw)<=f.bundle_cap(caps)+MIB,'TRANSFER_CAP')
        print('C5_RESOURCE '+json.dumps({'scenario':name,'python':sys.version.split()[0],
              'platform':sys.platform,'baseline_peak_rss_bytes':base,'rows':len(rows),
              'body_bytes':caps['body'],'max_archive_bytes':max(scratch),'max_entries':members,
              'accepted_totals':totals,'scratch_peak_logical_bytes':max(scratch),
              'collection_logical_upper_bound_bytes':stages[1]['retained_logical_bytes']+max(scratch),
              'bundle_bytes':ident['bytes'],'outer_zip_bytes':len(raw),'stages':stages,
              'peak_after_assertions_bytes':peak(),'status':'PASS'},sort_keys=True),flush=True)

def boundaries():
    # Measure actual accepted fixture costs, then check equality and one byte less.
    with tempfile.TemporaryDirectory(prefix='c5-inert-boundaries-') as temp:
        parent=Path(temp);items=[item(1),item(2)]
        rows,bindings,replay=setup(items);caps=caps_for(rows)
        path,digest=f._collect(rows,'boundary',bindings,caps,f.FIXTURE_SCOPE,replay.get,nullcontext,parent)
        first=f.verify_generation(path,digest,rows,'boundary',scope=f.FIXTURE_SCOPE,bindings=bindings,caps=caps)
        exact={**caps,**first['accepted_totals']}
        rows,bindings,replay=setup(items)
        path,digest=f._collect(rows,'boundary',bindings,exact,f.FIXTURE_SCOPE,replay.get,nullcontext,parent)
        settled=f.verify_generation(path,digest,rows,'boundary',scope=f.FIXTURE_SCOPE,bindings=bindings,caps=exact)
        need(settled['verified_count']==2 and settled['accepted_totals']==first['accepted_totals'],'EQUAL_CAP')
        results={}
        for field,reason in (('expanded','BATCH_EXPANSION_LIMIT'),('notice','BATCH_EXPANSION_LIMIT'),
                             ('evidence','EVIDENCE_BATCH_LIMIT')):
            rows,bindings,replay=setup(items)
            # One byte below the first receipt's exact requirement; no second GET.
            receipt=json.loads((path/'wheel-001-evidence.json').read_bytes())['receipt']
            required={'expanded':receipt['expanded_bytes'],'notice':receipt['notice_bytes'],
                      'evidence':(path/'wheel-001-evidence.json').stat().st_size}[field]
            under={**exact,field:required-1}
            bad,sha=f._collect(rows,'boundary',bindings,under,f.FIXTURE_SCOPE,replay.get,nullcontext,parent)
            manifest=f.verify_generation(bad,sha,rows,'boundary',scope=f.FIXTURE_SCOPE,bindings=bindings,caps=under)
            result=a.parse((bad/'request-001-result.json').read_bytes())
            need(manifest['verified_count']==0 and manifest['attempted_count']==1 and len(replay.requests)==1
                 and manifest['accepted_totals']=={'expanded':0,'notice':0,'evidence':0}
                 and result['inspection_reason']==reason and not (bad/'wheel-001-evidence.json').exists(),
                 'SCALED_REFUSAL')
            results[field]={'cap':required-1,'reason':reason,'attempted':1,'verified':0}
        before=logical(parent);rows,bindings,replay=setup(items)
        try:
            f._collect(rows,'boundary',bindings,{**exact,'body':exact['body']-1},f.FIXTURE_SCOPE,
                       replay.get,nullcontext,parent)
        except w.Blocked as exc:
            need(str(exc)=='RESIDUAL_BODY_LIMIT' and not replay.requests and logical(parent)==before,'BODY_REFUSAL')
            results['body']={'cap':exact['body']-1,'reason':str(exc),'attempted':0,'verified':0}
        else: raise AssertionError('BODY_ACCEPTED')
        print('C5_BOUNDARIES '+json.dumps({'platform':sys.platform,'exact':exact,'one_under':results,
                                           'status':'PASS'},sort_keys=True),flush=True)

if __name__=='__main__':
    need(f.ARMED is False,'DISARMED')
    need(len(sys.argv)==2 and sys.argv[1] in ('stored','dense','notices63','boundaries'),'FIXTURE_ONLY')
    with patch.object(f.http.client,'HTTPSConnection',side_effect=AssertionError('NO_NETWORK')), \
         patch.object(f,'build_opener',side_effect=AssertionError('NO_SERVICE')):
        if sys.argv[1]=='boundaries': boundaries()
        else: collect(sys.argv[1])
